UPDATE lessons SET title='Year 7, Lesson 12: Digital basics and data', data=json_patch(data,'{"child_mission":"Strong practice: unique passwords, not shared, long and hard to guess; use school-approved managers if provided. Never embed passwords in shared screenshots or slideshows. Teachers reset portals through official channels — not through classmates.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same technology/design idea to a new object or material, then compare two pieces of evidence for strength.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nSafer response if a friend asks for your login: refuse and suggest official reset help, or hand over the password once?\n\nFEEDBACK\nRefuse and use official help. Sharing logins breaks rules and safety.\n\nWATCH FOR\nWriting passwords on a sticky note under the keyboard as the main strategy.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nCreate a four-rule password poster for your class (unique, length, no sharing, official resets). No real passwords written.\n\nWrite a short reflection naming one observation, criterion or step you corrected and why.","interactive_activities":null,"learning_area":"Information and Software Technology","learning_intention":"Strong practice: unique passwords, not shared, long and hard to guess; use school-approved managers if provided. Never embed passwords in shared screenshots or slideshows. Teachers reset portals through official channels — not through classmates.","lesson_number":12,"lesson_role":"Apply","materials":["Paper or typed answer space","Pencil","Optional: safe classroom tools/materials under teacher supervision","Device only when the lesson requires digital work"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["IST5-DAT-01"],"parent_notes":"Parent: Marking guidance for the independent task: Create a four-rule password poster for your class (unique, length, no sharing, official resets). No real passwords written. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Sample: original example using password on new material; names a specific word, source or choice and explains its effect.\n\nParent: Written model 2: Sample error: Writing passwords on a sticky note under the keyboard as the main strategy.. Correction: Refuse and use official help.. Why it helps the audience is stated.\n\nParent: Likely misconception: Writing passwords on a sticky note under the keyboard as the main strategy. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Produce a fresh example demonstrating password on new material (not the worked model). Explain the particular words, sources or choices that make it work.\n\nParent: Short-answer focus 2: Name one likely error with password, correct it, and explain why the correction helps a reader or audience.\n\nParent: Marking notes: Accept original work about password with a specific supporting detail. Reject copied model wording with no new material. / Accept a misconception, a correction, and a purpose-linked reason for password. Reject corrections that do not change the inaccurate idea..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":0,"explanation":"This matches the taught method for password. The other choices miss a key step or use a common mistake.","options":["Refuse and use official help","Writing passwords on a sticky note under the keyboard as the main strategy","Ignore the observation or criteria and invent a more exciting result","Copy the model objects and call that independent work"],"questi